package com.yeyamo_mobile.api.gamification_service.infrastructure.persistence;import java.time.Instant;import java.util.UUID;import jakarta.persistence.*;
@Entity@Table(name="xp_ledger")public class XpLedgerEntity{@Id UUID id;@Column(name="event_id",nullable=false,unique=true)UUID eventId;@Column(name="user_id",nullable=false,length=120)String userId;@Column(nullable=false)int points;@Column(nullable=false,length=80)String reason;@Column(name="source_id",nullable=false,length=160)String sourceId;@Column(name="occurred_at",nullable=false)Instant occurredAt;@Column(name="created_at",nullable=false)Instant createdAt;}
